//! 🧪️ Actual inline scalar receipt bytes preserve failed effects and maximum-width original identities.
use super::*;
#[test]
fn original_input_admission_requires_actual_return_proof_without_new_frame_storage(){let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let expected=fixture["failureHex"].as_str().unwrap();let mut bytes=[0u8;136];for(index,pair)in expected.as_bytes().chunks_exact(2).enumerate(){bytes[index]=u8::from_str_radix(std::str::from_utf8(pair).unwrap(),16).unwrap()}bytes[4]=4;bytes[6]=0;for flags in 0..8{bytes[5]=flags;let(result,heap)=observe(||OriginalActorFixedReceipt::read(&bytes));assert_eq!(heap,(0,0));assert_eq!(result.is_ok(),fixture["inputAdmissionFlags"][flags as usize].as_bool().unwrap());if let Ok(call)=result{assert_eq!(call.kind,OriginalActorFixedKind::InputAdmission{ready:flags&1!=0,input_returned:flags&2!=0,refusal:None});let mut receipt=OriginalActorFixedReceipt::empty();let(_,heap)=observe(||receipt.write(call));assert_eq!(heap,(0,0));assert_eq!(receipt.bytes(),&bytes);}}}
#[test]
fn original_actor_receipt_loan_refuses_body_before_exact_resident_handback(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("lifecycle.json")).unwrap();let bytes:Vec<u8>=serde_json::from_str::<serde_json::Value>(include_str!("🧫️fixtures/🔣️.json")).unwrap()["failureHex"].as_str().unwrap().as_bytes().chunks_exact(2).map(|pair|u8::from_str_radix(std::str::from_utf8(pair).unwrap(),16).unwrap()).collect();let original=OriginalActorFixedReceipt::read(&bytes).unwrap();let mut receipt=OriginalActorFixedReceipt::empty();let pointer=receipt.bytes().as_ptr()as usize;let mut bodies=0;
 for event in fixture["events"].as_array().unwrap(){let offset=event["offset"].as_i64().unwrap();let length=event["length"].as_u64().unwrap()as usize;let((accepted,known),heap)=observe(||{let accepted=if event["operation"]=="produce"{receipt.produce(||{bodies+=1;original}).is_ok()}else{receipt.hand_back(pointer.wrapping_add_signed(offset as isize),length)};(accepted,receipt.owns_pointer(pointer.wrapping_add_signed(offset as isize)))});assert_eq!(heap,(0,0));assert_eq!(accepted,event["accepted"].as_bool().unwrap());assert_eq!(known,event["known"].as_bool().unwrap());assert_eq!(bodies,event["bodyCalls"].as_u64().unwrap());assert_eq!(receipt.bytes().as_ptr()as usize,pointer)}assert!(!receipt.is_borrowed());assert_eq!(observe(||drop(receipt)).1,(0,0));
}
fn observe<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);(value,(heap.requested_bytes,heap.released_bytes))}
#[test]
fn original_actor_fixed_native_receipt_preserves_raw_spend_and_all_u64_axes_without_heap(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let expected=fixture["failureHex"].as_str().unwrap();let expected:Vec<u8>=(0..expected.len()).step_by(2).map(|index|u8::from_str_radix(&expected[index..index+2],16).unwrap()).collect();
 let original=OriginalActorFixedCall{input:RetainedTurnInput{operation:71,generation:3,epoch:24,work:semio_framework_actor::OriginalActorTurnWork{clock_binding:711,absolute_deadline_us:1500,fuel:65536},grant:RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:7,maximum_capacity_bytes:512,maximum_release_bytes:512,maximum_depth:8}},spent:RetainedCloneProgress{copied_items:1,copied_bytes:7,..Default::default()},work_units_spent:4,kind:OriginalActorFixedKind::Failure{authority:None}};
 let(mut wire,heap)=observe(OriginalActorFixedReceipt::empty);assert_eq!(heap,(0,0));let backing=wire.bytes().as_ptr();let(_,heap)=observe(||wire.write(original));assert_eq!(heap,(0,0));assert_eq!(wire.bytes().as_slice(),expected);let(decoded,heap)=observe(||OriginalActorFixedReceipt::read(wire.bytes()));assert_eq!(heap,(0,0));assert_eq!(decoded.unwrap(),original);assert_eq!(wire.bytes().as_ptr(),backing);
 for kind in [None,Some(ValueRefusalKind::InvalidValue),Some(ValueRefusalKind::Canceled),Some(ValueRefusalKind::OwnershipLimit),Some(ValueRefusalKind::AllocationFailed),Some(ValueRefusalKind::WorkLimit),Some(ValueRefusalKind::DepthLimit),Some(ValueRefusalKind::UnsupportedOwner),Some(ValueRefusalKind::InvariantViolated)]{for variant in [OriginalActorFixedKind::Failure{authority:kind},OriginalActorFixedKind::Admission{ready:false,refusal:kind},OriginalActorFixedKind::Close{complete:false,blocked:false,refusal:kind}]{let actual=OriginalActorFixedCall{kind:variant,..original};let(decoded,heap)=observe(||{wire.write(actual);OriginalActorFixedReceipt::read(wire.bytes())});assert_eq!(heap,(0,0));assert_eq!(decoded.unwrap(),actual);}}
 let mut excessive=original;excessive.spent.copied_items=9;excessive.spent.copied_bytes=8192;let(decoded,heap)=observe(||{wire.write(excessive);OriginalActorFixedReceipt::read(wire.bytes())});assert_eq!(heap,(0,0));assert_eq!(decoded.unwrap(),excessive);assert!(excessive.input.return_original(excessive.spent,excessive.work_units_spent).is_err());
 let maximum=OriginalActorFixedCall{input:RetainedTurnInput{operation:u64::MAX,generation:u64::MAX,epoch:u64::MAX,work:semio_framework_actor::OriginalActorTurnWork{clock_binding:u64::MAX,absolute_deadline_us:u64::MAX,fuel:u64::MAX},grant:RetainedCloneGrant{maximum_items:usize::MAX,maximum_copy_bytes:usize::MAX,maximum_capacity_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:usize::MAX}},spent:RetainedCloneProgress{copied_items:usize::MAX,copied_bytes:usize::MAX,retained_capacity_bytes:usize::MAX,released_bytes:usize::MAX},work_units_spent:u64::MAX,..original};let(decoded,heap)=observe(||{wire.write(maximum);OriginalActorFixedReceipt::read(wire.bytes())});assert_eq!(heap,(0,0));assert_eq!(decoded.unwrap(),maximum);assert_eq!(&wire.bytes()[8..32],&[255;24]);
 for(index,value)in[(0,0),(4,5),(5,3),(6,9),(7,1)]{let mut invalid=*wire.bytes();invalid[index]=value;let(result,heap)=observe(||OriginalActorFixedReceipt::read(&invalid));assert_eq!(heap,(0,0));assert!(result.is_err());}let(result,heap)=observe(||OriginalActorFixedReceipt::read(&wire.bytes()[..103]));assert_eq!(heap,(0,0));assert!(result.is_err());assert_eq!(observe(||drop(wire)).1,(0,0));
}
